  .then(r => r.text())
  .then(xml => {
    const parser = new DOMParser();
    const doc    = parser.parseFromString(xml, 'application/xml');

    // Build node index: id → [lat, lon]
    const nodes = {};
    doc.querySelectorAll('node').forEach(n => {
      nodes[n.getAttribute('id')] = [
        parseFloat(n.getAttribute('lat')),
        parseFloat(n.getAttribute('lon')),
      ];
    });

    // Render ways
    doc.querySelectorAll('way').forEach(way => {
      const refs = [...way.querySelectorAll('nd')].map(nd => nodes[nd.getAttribute('ref')]).filter(Boolean);
      if (refs.length < 2) return;

      // collect tags
      const tags = {};
      way.querySelectorAll('tag').forEach(t => { tags[t.getAttribute('k')] = t.getAttribute('v'); });

      const style = styleForWay(tags);
      const closed = refs[0][0]===refs[refs.length-1][0] && refs[0][1]===refs[refs.length-1][1];
